"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["23126"],{15836(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.eliminacao_enem_fora_de_processo_enem","status":422,"titulo":"A regra de elimina\xe7\xe3o s\xf3 se aplica quando a classifica\xe7\xe3o est\xe1 configurada como baseada em ENEM"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.eliminacao_enem_fora_de_processo_enem","requisitos":[],"oQueAconteceu":["A configura\xe7\xe3o de classifica\xe7\xe3o declara uma ou mais regras de elimina\xe7\xe3o com\\nc\xf3digo `ELIMINACAO_CORTE_EM_AREA` ou `ELIMINACAO_ZERO_EM_AREA`, mas `baseadoEmEnem` \xe9\\n`false`. As duas regras dependem da estrutura de pontua\xe7\xe3o por \xe1rea do\\nENEM \u2014 sem o processo estar marcado como baseado em ENEM, elas n\xe3o t\xeam nota\\npor \xe1rea contra a qual verificar o corte ou o zero. `ELIMINACAO_NOTA_MINIMA_ETAPA`\\nn\xe3o entra nessa confer\xeancia \u2014 depende s\xf3 da nota de uma etapa do processo,\\nindependente de ENEM.","Embora o c\xf3digo pare\xe7a pertencer \xe0 fam\xedlia `ConfiguracaoClassificacao` (\xe9\\nlevantado dentro do `Criar` dela, sobre dois campos que s\xe3o dela mesma \u2014\\n`RegrasEliminacao` e `BaseadoEmEnem`), o registro p\xfablico classifica esta\\ncausa como `ProcessoSeletivo.*`. \xc9 resqu\xedcio hist\xf3rico: `BaseadoEmEnem`\\nnasceu derivado de `ProcessoSeletivo.TipoProcesso` e s\xf3 depois passou a ser\\num sinal declarado na pr\xf3pria configura\xe7\xe3o \u2014 o prefixo do c\xf3digo p\xfablico\\nficou de quando a depend\xeancia ainda era do tipo do processo, n\xe3o da\\nconfigura\xe7\xe3o.","Esta confer\xeancia roda de forma **independente** de a classifica\xe7\xe3o ser local ou\\nimportada \u2014 corre sempre, por \xfaltimo, depois do bloco que confere coer\xeancia\\nde arredondamento/elimina\xe7\xe3o para cada um dos dois tipos de c\xe1lculo. No\\ncaminho de defini\xe7\xe3o, por isso, pode coexistir na mesma resposta com\\nqualquer uma das causas desse bloco:\\n[`eliminacao_indevida`](/erros/uniplus.selecao.configuracao_classificacao.eliminacao_indevida)\\n(uma configura\xe7\xe3o importada com regras de elimina\xe7\xe3o incoerentes E sem\\n`baseadoEmEnem` reprova as duas ao mesmo tempo \u2014 reprovar por importa\xe7\xe3o n\xe3o\\nesvazia a lista de regras que esta confer\xeancia tamb\xe9m percorre),\\n[`arredondamento_indevido`](/erros/uniplus.selecao.configuracao_classificacao.arredondamento_indevido),\\n[`casas_arredondamento_indevido`](/erros/uniplus.selecao.configuracao_classificacao.casas_arredondamento_indevido),\\n[`arredondamento_obrigatorio`](/erros/uniplus.selecao.configuracao_classificacao.arredondamento_obrigatorio)\\ne\\n[`casas_arredondamento_obrigatorio`](/erros/uniplus.selecao.configuracao_classificacao.casas_arredondamento_obrigatorio)\\n(acumula, ADR-0125)."],"comoResolver":["Marque a configura\xe7\xe3o como `baseadoEmEnem: true` se o processo de fato usa a\\nestrutura de pontua\xe7\xe3o por \xe1rea do ENEM. Caso contr\xe1rio, remova as regras de\\nelimina\xe7\xe3o `ELIMINACAO_CORTE_EM_AREA`/`ELIMINACAO_ZERO_EM_AREA` \u2014 s\xf3\\n`ELIMINACAO_NOTA_MINIMA_ETAPA` se aplica fora desse contexto."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);